// 4. 初始化函數
function init() {
  // A. 載入資料庫
  loadDatabase();
  
  // B. 綁定事件監聽器
  bindEvents();
  
  // C. 初始化樓層 Slider UI 顯示
  syncSliderUI();
  
  // D. 渲染網格
  renderGallery();
  
  // E. 更新統計徽章
  updateStatsBadge();
  
  // F. 初始化手機版 UI
  initMobileUI();
}

// LocalStorage Safe Fallback Wrapper (Prevents CORS/Security crashes under file:// protocol)
const memoryStorage = {};
const safeStorage = {
  getItem(key) {
    try {
      return window.localStorage.getItem(key);
    } catch (e) {
      console.warn("LocalStorage getItem failed, using memory fallback: ", e);
      return memoryStorage[key] || null;
    }
  },
  setItem(key, val) {
    try {
      window.localStorage.setItem(key, val);
    } catch (e) {
      console.warn("LocalStorage setItem failed, using memory fallback: ", e);
      memoryStorage[key] = val;
    }
  }
};

// 5. 資料庫操作 (LocalStorage)
function loadDatabase() {
  const localData = safeStorage.getItem("facade_finder_db");
  if (localData) {
    try {
      facades = JSON.parse(localData);
      // 自動檢查並合併預設素材中缺失的項目 (例如新增的 15 張原本內置圖片)
      let modified = false;
      DEFAULT_FACADES.forEach(defItem => {
        if (!facades.some(f => f.title === defItem.title)) {
          facades.push(defItem);
          modified = true;
        }
      });
      if (modified) {
        saveDatabase();
      }
    } catch (e) {
      console.error("載入 LocalStorage 失敗，改用預設資料", e);
      facades = [...DEFAULT_FACADES];
    }
  } else {
    facades = [...DEFAULT_FACADES];
    saveDatabase();
  }

  // 載入 Pinterest 歷史記錄
  const historyData = safeStorage.getItem("facade_finder_pinterest_history");
  if (historyData) {
    try {
      pinterestHistory = JSON.parse(historyData);
    } catch (e) {
      pinterestHistory = [];
    }
  } else {
    pinterestHistory = [
      "https://www.pinterest.com/brianarchitect/facade-material-texture/",
      "https://www.pinterest.com/mizhen99/%E5%BB%BA%E7%AF%89%E5%A4%96%E8%A7%80%E7%AB%8B%E9%9D%A2-architectural-facade/",
      "https://www.pinterest.com/r_architecture/facades/"
    ];
    savePinterestHistory();
  }
}

function saveDatabase() {
  safeStorage.setItem("facade_finder_db", JSON.stringify(facades));
  updateStatsBadge();
}

function savePinterestHistory() {
  safeStorage.setItem("facade_finder_pinterest_history", JSON.stringify(pinterestHistory));
}

function updateStatsBadge() {
  const total = facades.length;
  const favs = facades.filter(f => f.isFavorite).length;
  
  if (DOM.totalCountBadge) DOM.totalCountBadge.textContent = total;
  if (DOM.favCountBadge) DOM.favCountBadge.textContent = favs;
}

// 6. 核心渲染邏輯 (Rendering & Filtering)
function renderGallery() {
  if (state.currentView !== "local-library") {
    DOM.galleryGrid.style.display = "none";
    DOM.emptyState.style.display = "none";
    return;
  }
  // A. 篩選 (Filtering)
  let filtered = facades.filter(item => {
    // 1. 關鍵字搜尋 (搜尋標題、風格、搭配建材、設計描述)
    if (state.filters.search) {
      const q = state.filters.search.toLowerCase();
      const matchTitle = item.title.toLowerCase().includes(q);
      const matchStyle = item.style.toLowerCase().includes(q);
      const matchMaterials = item.materials.some(m => m.toLowerCase().includes(q));
      const matchNotes = item.notes.toLowerCase().includes(q);
      if (!matchTitle && !matchStyle && !matchMaterials && !matchNotes) return false;
    }
    
    // 2. 建材分類多選篩選 (AND 邏輯 - 必須包含所有被勾選的建材)
    if (state.filters.materials.length > 0) {
      const hasAllSelectedMaterials = state.filters.materials.every(m => item.materials.includes(m));
      if (!hasAllSelectedMaterials) return false;
    }
    
    // 3. 建築風格多選篩選 (OR 邏輯 - 包含被勾選風格的其中一個)
    if (state.filters.styles.length > 0) {
      const matchAnyStyle = state.filters.styles.includes(item.style);
      if (!matchAnyStyle) return false;
    }
    
    // 4. 樓層數篩選
    // a. 先依據預設分組過濾
    if (state.filters.floorPreset !== "all") {
      const [minP, maxP] = state.filters.floorPreset.split("-").map(Number);
      if (item.floors < minP || item.floors > maxP) return false;
    }
    // b. 再依據拉桿範圍過濾
    if (item.floors < state.filters.floorRange.min || item.floors > state.filters.floorRange.max) {
      return false;
    }
    
    // 5. 僅顯示收藏
    if (state.filters.favoritesOnly && !item.isFavorite) return false;
    
    return true;
  });

  // B. 排序 (Sorting)
  if (state.sortBy === "floor-asc") {
    filtered.sort((a, b) => a.floors - b.floors);
  } else if (state.sortBy === "floor-desc") {
    filtered.sort((a, b) => b.floors - a.floors);
  } else if (state.sortBy === "newest") {
    filtered.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  }
  // "default" 則維持原本的順序 (預設預載在前，自訂最新在後)

  // C. 渲染 HTML
  DOM.galleryGrid.innerHTML = "";
  
  if (filtered.length === 0) {
    DOM.emptyState.style.display = "flex";
    DOM.galleryGrid.style.display = "none";
  } else {
    DOM.emptyState.style.display = "none";
    DOM.galleryGrid.style.display = "grid";
    
    filtered.forEach(item => {
      const card = document.createElement("article");
      card.className = "facade-card";
      card.setAttribute("data-id", item.id);
      
      const materialsHTML = item.materials.map(m => `<span class="card-tag">${m}</span>`).join("");
      
      card.innerHTML = `
        <div class="card-img-wrapper">
          <img src="${item.image}" alt="${item.title}" loading="lazy">
          <button class="card-fav-btn ${item.isFavorite ? 'active' : ''}" data-id="${item.id}" title="${item.isFavorite ? '取消收藏' : '加入收藏'}">
            <span class="material-symbols-outlined">bookmark</span>
          </button>
          <span class="card-floor-badge">${item.floors} F</span>
          <span class="card-style-badge">${item.style}風</span>
        </div>
        <div class="card-info" style="display: flex; flex-direction: column; justify-content: space-between; flex-grow: 1;">
          <div>
            <div class="card-title-row">
              <h3 class="card-title">${item.title}</h3>
            </div>
            <div class="card-tags" style="margin-bottom: 8px;">
              ${materialsHTML}
            </div>
          </div>
          <button class="select-direct-btn" data-id="${item.id}" style="width: 100%; padding: 6px; background: #10b981; color: white; border: none; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 11px; margin-top: 4px; display: flex; align-items: center; justify-content: center; gap: 4px; transition: background 0.2s; font-family: var(--font-chinese);" onmouseover="this.style.background='#0d9488'" onmouseout="this.style.background='#10b981'">
            <span class="material-symbols-outlined" style="font-size: 13px;">check_circle</span> 選擇此立面匯入
          </button>
        </div>
      `;
      
      // 點擊卡片開啟詳情
      card.addEventListener("click", (e) => {
        // 如果點擊的是收藏按鈕或選擇按鈕，則不觸發詳情燈箱
        if (e.target.closest(".card-fav-btn") || e.target.closest(".select-direct-btn")) return;
        showDetailModal(item.id);
      });
      
      // 收藏按鈕事件
      const favBtn = card.querySelector(".card-fav-btn");
      favBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        toggleFavorite(item.id);
      });

      // 選擇按鈕事件
      const selectBtn = card.querySelector(".select-direct-btn");
      if (selectBtn) {
        selectBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          const targetWindow = window.opener || window.parent;
          if (targetWindow) {
            targetWindow.postMessage({
              type: 'select-facade',
              image: item.image,
              title: item.title,
              facadeType: item.style + '風格'
            }, '*');
          }
        });
      }
      
      DOM.galleryGrid.appendChild(card);
    });
  }
  
  // D. 更新上方篩選提示條
  renderActiveFiltersBar();
}

// 渲染篩選提示標籤
function renderActiveFiltersBar() {
  const activeTags = [];
  
  // 關鍵字
  if (state.filters.search) {
    activeTags.push({ type: 'search', label: `關鍵字: "${state.filters.search}"` });
  }
  
  // 建材
  state.filters.materials.forEach(m => {
    activeTags.push({ type: 'material', val: m, label: m });
  });
  
  // 風格
  state.filters.styles.forEach(s => {
    activeTags.push({ type: 'style', val: s, label: `${s}風` });
  });
  
  // 樓層預設
  if (state.filters.floorPreset !== "all") {
    let presetLabel = "";
    if (state.filters.floorPreset === "1-5") presetLabel = "低層 (1-5F)";
    else if (state.filters.floorPreset === "6-12") presetLabel = "中層 (6-12F)";
    else if (state.filters.floorPreset === "13-999") presetLabel = "高層 (13F+)";
    activeTags.push({ type: 'floorPreset', label: presetLabel });
  }
  
  // 樓層範圍 (若有異動)
  if (state.filters.floorRange.min > 1 || state.filters.floorRange.max < 100) {
    activeTags.push({ type: 'floorRange', label: `樓層: ${state.filters.floorRange.min}-${state.filters.floorRange.max}F` });
  }
  
  // 收藏
  if (state.filters.favoritesOnly) {
    activeTags.push({ type: 'favOnly', label: "僅收藏" });
  }
  
  if (activeTags.length > 0) {
    DOM.activeFiltersBar.style.display = "flex";
    DOM.activeTagsList.innerHTML = activeTags.map(tag => {
      let dataAttr = '';
      if (tag.type === 'material') dataAttr = `data-type="material" data-val="${tag.val}"`;
      if (tag.type === 'style') dataAttr = `data-type="style" data-val="${tag.val}"`;
      if (tag.type === 'floorPreset') dataAttr = `data-type="floorPreset"`;
      if (tag.type === 'floorRange') dataAttr = `data-type="floorRange"`;
      if (tag.type === 'search') dataAttr = `data-type="search"`;
      if (tag.type === 'favOnly') dataAttr = `data-type="favOnly"`;
      
      return `
        <span class="active-tag">
          <span>${tag.label}</span>
          <button class="remove-filter-tag-btn" ${dataAttr} aria-label="移除篩選">
            <span class="material-symbols-outlined">close</span>
          </button>
        </span>
      `;
    }).join("");
    
    // 綁定個別刪除標籤事件
    DOM.activeTagsList.querySelectorAll(".remove-filter-tag-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        const type = btn.getAttribute("data-type");
        const val = btn.getAttribute("data-val");
        removeSingleFilter(type, val);
      });
    });
  } else {
    DOM.activeFiltersBar.style.display = "none";
  }
}

// 7. 篩選控制項處理 (Filter Handling)
function removeSingleFilter(type, val) {
  if (type === 'search') {
    state.filters.search = "";
    DOM.searchInput.value = "";
    DOM.clearSearchBtn.style.display = "none";
  } else if (type === 'material') {
    state.filters.materials = state.filters.materials.filter(m => m !== val);
    const cb = document.querySelector(`#material-filters input[value="${val}"]`);
    if (cb) cb.checked = false;
  } else if (type === 'style') {
    state.filters.styles = state.filters.styles.filter(s => s !== val);
    const cb = document.querySelector(`#style-filters input[value="${val}"]`);
    if (cb) cb.checked = false;
  } else if (type === 'floorPreset') {
    state.filters.floorPreset = "all";
    document.querySelectorAll("#floor-range-presets button").forEach(btn => {
      btn.classList.toggle("active", btn.getAttribute("data-range") === "all");
    });
  } else if (type === 'floorRange') {
    state.filters.floorRange = { min: 1, max: 100 };
    DOM.floorMin.value = 1;
    DOM.floorMax.value = 100;
    syncSliderUI();
  } else if (type === 'favOnly') {
    state.filters.favoritesOnly = false;
    DOM.favOnlyBtn.classList.remove("active");
  }
  
  syncFiltersAndTriggerSearch(true);
}

function clearAllFilters() {
  state.filters.search = "";
  state.filters.materials = [];
  state.filters.styles = [];
  state.filters.floorRange = { min: 1, max: 100 };
  state.filters.floorPreset = "all";
  state.filters.favoritesOnly = false;
  
  // 重置 UI 控制項
  DOM.searchInput.value = "";
  DOM.clearSearchBtn.style.display = "none";
  DOM.favOnlyBtn.classList.remove("active");
  
  document.querySelectorAll("#material-filters input").forEach(cb => cb.checked = false);
  document.querySelectorAll("#style-filters input").forEach(cb => cb.checked = false);
  
  document.querySelectorAll("#floor-range-presets button").forEach(btn => {
    btn.classList.toggle("active", btn.getAttribute("data-range") === "all");
  });
  
  DOM.floorMin.value = 1;
  DOM.floorMax.value = 100;
  syncSliderUI();
  
  syncFiltersAndTriggerSearch(true);
  showToast("已重置所有篩選條件");
}

// 樓層拉桿 UI 同步與事件
function syncSliderUI() {
  let minVal = parseInt(DOM.floorMin.value);
  let maxVal = parseInt(DOM.floorMax.value);
  
  // 防止交叉
  if (minVal > maxVal) {
    let temp = minVal;
    minVal = maxVal;
    maxVal = temp;
    DOM.floorMin.value = minVal;
    DOM.floorMax.value = maxVal;
  }
  
  state.filters.floorRange.min = minVal;
  state.filters.floorRange.max = maxVal;
  DOM.sliderRangeVal.textContent = `${minVal} - ${maxVal} F`;
}

// 收藏功能切換
function toggleFavorite(id) {
  const item = facades.find(f => f.id === id);
  if (item) {
    item.isFavorite = !item.isFavorite;
    saveDatabase();
    
    // 如果在詳情燈箱內，同步更新燈箱 UI
    if (DOM.detailModal.classList.contains("active")) {
      const activeId = DOM.detailModal.getAttribute("data-active-id");
      if (activeId === id) {
        DOM.detailFavToggle.classList.toggle("active", item.isFavorite);
        DOM.detailFavToggle.setAttribute("title", item.isFavorite ? '取消收藏' : '加入收藏');
      }
    }
    
    renderGallery();
    showToast(item.isFavorite ? "已加入我的收藏" : "已取消收藏");
  }
}

// 8. 詳情燈箱 (Detail Lightbox Modal)
function showDetailModal(id) {
  const item = facades.find(f => f.id === id);
  if (!item) return;
  
  DOM.detailModal.setAttribute("data-active-id", id);
  
  // 設定圖片、最愛與基本文字
  DOM.detailImage.src = item.image;
  DOM.detailFavToggle.classList.toggle("active", item.isFavorite);
  DOM.detailFavToggle.setAttribute("title", item.isFavorite ? '取消收藏' : '加入收藏');
  
  DOM.detailTitle.textContent = item.title;
  DOM.detailFloor.textContent = `${item.floors} F`;
  DOM.detailStyle.textContent = `${item.style}風`;
  
  // 建立建材標籤
  DOM.detailMaterials.innerHTML = item.materials.map(m => `<span class="tag">${m}</span>`).join("");
  
  // 建立色調配色表
  DOM.detailPalette.innerHTML = item.palette.map(hex => `
    <div class="color-swatch-wrapper">
      <div class="color-swatch" style="background-color: ${hex};"></div>
      <span class="color-hex">${hex.toUpperCase()}</span>
    </div>
  `).join("");
  
  // 設定備忘筆記
  DOM.detailMemo.value = item.notes || "";
  DOM.memoSavedIndicator.classList.remove("active");
  
  // 新增/修改時間
  const createdDate = new Date(item.createdAt);
  DOM.detailTime.textContent = `加入時間：${createdDate.getFullYear()}/${String(createdDate.getMonth() + 1).padStart(2, '0')}/${String(createdDate.getDate()).padStart(2, '0')}`;
  
  // 設定刪除按鈕 (預設立面可隱藏刪除或允許全部刪除)
  if (item.isDefault) {
    DOM.detailDeleteBtn.style.display = "none"; // 預設立面不提供刪除
  } else {
    DOM.detailDeleteBtn.style.display = "flex";
  }
  
  // 開啟 Modal
  DOM.detailModal.classList.add("active");
  DOM.detailModal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden"; // 避免底層滾動
  
  // 重新綁定詳情中的收藏按鈕
  DOM.detailFavToggle.onclick = () => {
    toggleFavorite(id);
  };
  
  // 詳情中的備忘自動儲存
  DOM.detailMemo.oninput = () => {
    clearTimeout(autoSaveTimeout);
    DOM.memoSavedIndicator.classList.remove("active");
    
    autoSaveTimeout = setTimeout(() => {
      item.notes = DOM.detailMemo.value;
      saveDatabase();
      DOM.memoSavedIndicator.classList.add("active");
      
      // 更新網格，以防篩選條件跟筆記有關
      renderGallery();
    }, 800); // 800ms 防抖動自動存檔
  };
  
  // 匯入按鈕事件
  const importBtn = document.getElementById('import-to-app-btn');
  if (importBtn) {
    importBtn.onclick = () => {
      const targetWindow = window.opener || window.parent;
      if (targetWindow) {
        targetWindow.postMessage({
          type: 'select-facade',
          image: item.image,
          title: item.title,
          facadeType: item.style + '風格'
        }, '*');
      }
      closeDetailModal();
    };
  }
  
  // 刪除按鈕事件
  DOM.detailDeleteBtn.onclick = () => {
    if (confirm(`確定要刪除「${item.title}」素材嗎？此操作無法還原。`)) {
      deleteFacade(id);
    }
  };
}

function closeDetailModal() {
  DOM.detailModal.classList.remove("active");
  DOM.detailModal.setAttribute("aria-hidden", "true");
  DOM.detailModal.removeAttribute("data-active-id");
  document.body.style.overflow = "";
}

// 刪除素材
function deleteFacade(id) {
  facades = facades.filter(f => f.id !== id);
  saveDatabase();
  closeDetailModal();
  renderGallery();
  showToast("已成功刪除素材");
}

// 9. 新增素材表單與圖片處理 (Add Material Modal)
function openAddModal() {
  DOM.materialForm.reset();
  currentUploadImage = null;
  DOM.imagePreviewContainer.style.display = "none";
  DOM.imagePreview.src = "";
  DOM.dragDropZone.style.display = "flex";
  
  // 預設切換到上傳本機分頁
  switchUploadTab("upload-file");
  
  DOM.addModal.classList.add("active");
  DOM.addModal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}

function closeAddModal() {
  DOM.addModal.classList.remove("active");
  DOM.addModal.setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
}

// 切換上傳分頁
function switchUploadTab(tabId) {
  document.querySelectorAll(".upload-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.getAttribute("data-tab") === tabId);
  });
  
  document.querySelectorAll(".upload-tab-content").forEach(content => {
    content.classList.toggle("active", content.id === `tab-${tabId}`);
  });
  
  // 如果切換分頁，清除對應的資料
  if (tabId === "upload-file") {
    DOM.urlInput.value = "";
  } else {
    currentUploadImage = null;
    DOM.fileInput.value = "";
  }
}

// 本地圖片壓縮與轉換為 Base64 格式
function processImageFile(file) {
  if (!file.type.startsWith("image/")) {
    showToast("錯誤：只能上傳圖片檔案");
    return;
  }
  
  const reader = new FileReader();
  reader.onload = function(e) {
    const rawImg = new Image();
    rawImg.onload = function() {
      // 建立 Canvas 進行本地壓縮 (最大寬度/高度為 1020px，以節省 LocalStorage 空間)
      const canvas = document.createElement("canvas");
      let width = rawImg.width;
      let height = rawImg.height;
      const MAX_SIZE = 1020;
      
      if (width > height) {
        if (width > MAX_SIZE) {
          height = Math.round((height * MAX_SIZE) / width);
          width = MAX_SIZE;
        }
      } else {
        if (height > MAX_SIZE) {
          width = Math.round((width * MAX_SIZE) / height);
          height = MAX_SIZE;
        }
      }
      
      canvas.width = width;
      canvas.height = height;
      
      const ctx = canvas.getContext("2d");
      ctx.drawImage(rawImg, 0, 0, width, height);
      
      // 轉為 JPG 格式，壓縮品質 0.8
      const compressedBase64 = canvas.toDataURL("image/jpeg", 0.8);
      currentUploadImage = compressedBase64;
      
      // 顯示預覽
      DOM.imagePreview.src = compressedBase64;
      DOM.imagePreviewContainer.style.display = "block";
      DOM.dragDropZone.style.display = "none";
    };
    rawImg.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

// 根據選擇的建材自動生成一套高質感的配色表 (防止 CORS 圖片 Canvas 取色出錯)
function generatePaletteByMaterials(materials) {
  const paletteMap = {
    "帷幕": ["#1b2a47", "#4f6b8c", "#a2b7cf", "#d9e2ec"],
    "石材": ["#e6dfd3", "#cbbba0", "#8c7b60", "#403628"],
    "鐵件": ["#22252a", "#434750", "#a36c4b", "#e8dacf"],
    "磁磚": ["#dfdbd2", "#aba392", "#665f50", "#efebdf"],
    "清水模": ["#8c9094", "#adb2b6", "#63676b", "#3b3e41"],
    "木質": ["#8e5f38", "#c2976e", "#563b22", "#e8d0b5"]
  };
  
  // 找尋所選建材中有對應的配色，多選時取第一個，若無對應則用預設灰色系
  const primaryMaterial = materials.find(m => paletteMap[m]);
  if (primaryMaterial) {
    return paletteMap[primaryMaterial];
  }
  return ["#4b5563", "#9ca3af", "#d1d5db", "#f3f4f6"];
}

// 送出新增素材表單
function handleFormSubmit(e) {
  e.preventDefault();
  
  const title = document.getElementById("form-title").value.trim();
  const floors = parseInt(document.getElementById("form-floor").value);
  
  // 風格
  const styleEl = document.querySelector('input[name="form-style"]:checked');
  const style = styleEl ? styleEl.value : "現代";
  
  // 建材 (多選)
  const materialEls = document.querySelectorAll('input[name="form-material"]:checked');
  const materials = Array.from(materialEls).map(el => el.value);
  
  if (materials.length === 0) {
    showToast("請至少選擇一種建材分類！");
    return;
  }
  
  // 圖片來源判斷 (本機上傳優先於網址)
  let imageSrc = "";
  if (currentUploadImage) {
    imageSrc = currentUploadImage;
  } else {
    const urlVal = DOM.urlInput.value.trim();
    if (urlVal) {
      imageSrc = urlVal;
    }
  }
  
  if (!imageSrc) {
    showToast("請上傳圖片或提供圖片外部網址！");
    return;
  }
  
  const notes = document.getElementById("form-memo").value.trim();
  
  // 自動匹配高雅調色盤
  const palette = generatePaletteByMaterials(materials);
  
  // 建立新立面物件
  const newFacade = {
    id: "user-" + Date.now(),
    title: title,
    image: imageSrc,
    floors: floors,
    materials: materials,
    style: style,
    notes: notes,
    palette: palette,
    isFavorite: false,
    isDefault: false,
    createdAt: new Date().toISOString()
  };
  
  // 新增至首位
  facades.unshift(newFacade);
  saveDatabase();
  
  closeAddModal();
  renderGallery();
  showToast(`已成功新增立面素材：「${title}」`);
}

// 10. 匯入與匯出資料庫 (JSON Backup)
function exportDatabase() {
  // 過濾掉 Base64 過大檔案或保留均可。這裡直接完整匯出所有自訂和收藏狀態
  const dataStr = JSON.stringify(facades, null, 2);
  const blob = new Blob([dataStr], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  
  const tempLink = document.createElement("a");
  tempLink.href = url;
  tempLink.download = `facades_library_export_${new Date().toISOString().slice(0,10)}.json`;
  document.body.appendChild(tempLink);
  tempLink.click();
  
  // 清理
  document.body.removeChild(tempLink);
  URL.revokeObjectURL(url);
  showToast("素材資料庫備份下載成功");
}

function handleImportFile(e) {
  const file = e.target.files[0];
  if (!file) return;
  
  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const importedData = JSON.parse(evt.target.result);
      
      // 基本資料格式驗證
      if (!Array.isArray(importedData)) {
        throw new Error("格式錯誤：根項目必須是陣列");
      }
      
      // 合併與防重複邏輯：保留匯入項目中不存在於現有 facades 中的部分，
      // 並允許覆蓋相同 ID 的項目（例如同步更新了備忘記）
      importedData.forEach(importedItem => {
        if (!importedItem.id) return;
        const index = facades.findIndex(f => f.id === importedItem.id);
        if (index > -1) {
          // 覆蓋
          facades[index] = importedItem;
        } else {
          // 新增
          facades.unshift(importedItem);
        }
      });
      
      saveDatabase();
      renderGallery();
      showToast("成功載入並合併素材資料庫！");
      DOM.importFile.value = ""; // 重置 input
    } catch (err) {
      showToast("載入檔案失敗：非有效的 JSON 資料格式");
      console.error(err);
    }
  };
  reader.readAsText(file);
}

// 11. Toast 提示訊息與事件綁定
function showToast(message) {
  DOM.toast.textContent = message;
  DOM.toast.classList.add("active");
  
  setTimeout(() => {
    DOM.toast.classList.remove("active");
  }, 3000);
}

// 事件綁定 (Event Listeners)
function bindEvents() {
  // 外部圖片網址輸入即時預覽
  DOM.urlInput.addEventListener("input", () => {
    const val = DOM.urlInput.value.trim();
    if (val) {
      DOM.imagePreview.src = val;
      DOM.imagePreviewContainer.style.display = "block";
      DOM.dragDropZone.style.display = "none";
    } else {
      DOM.imagePreviewContainer.style.display = "none";
      DOM.dragDropZone.style.display = "flex";
    }
  });

  // A. 搜尋與清除
  DOM.searchInput.addEventListener("input", (e) => {
    state.filters.search = e.target.value.trim();
    DOM.clearSearchBtn.style.display = state.filters.search ? "flex" : "none";
    syncFiltersAndTriggerSearch(false);
  });

  DOM.searchInput.addEventListener("keypress", (e) => {
    if (e.key === "Enter") {
      state.filters.search = DOM.searchInput.value.trim();
      DOM.clearSearchBtn.style.display = state.filters.search ? "flex" : "none";
      syncFiltersAndTriggerSearch(true);
    }
  });
  
  DOM.clearSearchBtn.addEventListener("click", () => {
    state.filters.search = "";
    DOM.searchInput.value = "";
    DOM.clearSearchBtn.style.display = "none";
    syncFiltersAndTriggerSearch(true);
  });
  
  // B. 排序改變
  DOM.sortSelect.addEventListener("change", (e) => {
    state.sortBy = e.target.value;
    renderGallery();
  });
  
  // C. 建材核取方塊篩選
  document.querySelectorAll("#material-filters input").forEach(cb => {
    cb.addEventListener("change", () => {
      const val = cb.value;
      if (cb.checked) {
        state.filters.materials.push(val);
      } else {
        state.filters.materials = state.filters.materials.filter(m => m !== val);
      }
      syncFiltersAndTriggerSearch(true);
    });
  });
  
  // D. 風格標籤篩選
  document.querySelectorAll("#style-filters input").forEach(cb => {
    cb.addEventListener("change", () => {
      const val = cb.value;
      if (cb.checked) {
        state.filters.styles.push(val);
      } else {
        state.filters.styles = state.filters.styles.filter(s => s !== val);
      }
      syncFiltersAndTriggerSearch(true);
    });
  });
  
  // E. 樓層預設按鈕篩選
  DOM.floorPresets.addEventListener("click", (e) => {
    const btn = e.target.closest(".floor-preset-btn");
    if (!btn) return;
    
    document.querySelectorAll("#floor-range-presets button").forEach(b => b.classList.remove("active"));
    btn.classList.add("active");
    
    state.filters.floorPreset = btn.getAttribute("data-range");
    syncFiltersAndTriggerSearch(true);
  });
  
  // F. 樓層自訂 Slider 事件
  DOM.floorMin.addEventListener("input", () => {
    syncSliderUI();
    syncFiltersAndTriggerSearch(true);
  });
  DOM.floorMax.addEventListener("input", () => {
    syncSliderUI();
    syncFiltersAndTriggerSearch(true);
  });
  
  // G. 收藏夾專屬篩選切換
  DOM.favOnlyBtn.addEventListener("click", () => {
    state.filters.favoritesOnly = !state.filters.favoritesOnly;
    DOM.favOnlyBtn.classList.toggle("active", state.filters.favoritesOnly);
    syncFiltersAndTriggerSearch(true);
  });
  
  // H. 重置全部篩選按鈕
  DOM.clearAllFiltersBtn.addEventListener("click", clearAllFilters);
  DOM.emptyState.querySelector(".reset-search-btn").addEventListener("click", clearAllFilters);
  
  // I. 詳情燈箱關閉
  DOM.detailCloseBtn.addEventListener("click", closeDetailModal);
  DOM.detailModal.addEventListener("click", (e) => {
    if (e.target === DOM.detailModal) closeDetailModal();
  });
  
  // J. 新增素材模態框開啟/關閉
  DOM.addMaterialBtn.addEventListener("click", openAddModal);
  DOM.addCloseBtn.addEventListener("click", closeAddModal);
  DOM.formCancelBtn.addEventListener("click", closeAddModal);
  DOM.addModal.addEventListener("click", (e) => {
    if (e.target === DOM.addModal) closeAddModal();
  });
  
  // 新增表單中的上傳 Tab 切換
  document.querySelectorAll(".upload-tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      switchUploadTab(btn.getAttribute("data-tab"));
    });
  });
  
  // 圖片選擇與拖曳
  DOM.dragDropZone.addEventListener("click", () => DOM.fileInput.click());
  DOM.fileInput.addEventListener("change", (e) => {
    if (e.target.files.length > 0) {
      processImageFile(e.target.files[0]);
    }
  });
  
  DOM.dragDropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    DOM.dragDropZone.classList.add("dragover");
  });
  DOM.dragDropZone.addEventListener("dragleave", () => {
    DOM.dragDropZone.classList.remove("dragover");
  });
  DOM.dragDropZone.addEventListener("drop", (e) => {
    e.preventDefault();
    DOM.dragDropZone.classList.remove("dragover");
    if (e.dataTransfer.files.length > 0) {
      processImageFile(e.dataTransfer.files[0]);
    }
  });
  
  // 移除圖片預覽
  DOM.removePreviewBtn.addEventListener("click", () => {
    currentUploadImage = null;
    DOM.fileInput.value = "";
    DOM.imagePreviewContainer.style.display = "none";
    DOM.imagePreview.src = "";
    DOM.dragDropZone.style.display = "flex";
  });
  
  // 送出表單
  DOM.materialForm.addEventListener("submit", handleFormSubmit);
  
  // K. 匯出與匯入資料
  DOM.exportBtn.addEventListener("click", exportDatabase);
  DOM.importTrigger.addEventListener("click", () => DOM.importFile.click());
  DOM.importFile.addEventListener("change", handleImportFile);
  
  // L. 手機側邊欄選單切換
  DOM.menuToggleBtn.addEventListener("click", () => {
    DOM.sidebar.classList.toggle("active");
    
    // 如果選單開啟，加上一個點擊背景關閉遮罩
    if (DOM.sidebar.classList.contains("active")) {
      const backdrop = document.createElement("div");
      backdrop.className = "sidebar-backdrop";
      backdrop.style.cssText = "position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(0,0,0,0.5);z-index:99;backdrop-filter:blur(3px);";
      document.body.appendChild(backdrop);
      
      backdrop.onclick = () => {
        DOM.sidebar.classList.remove("active");
        document.body.removeChild(backdrop);
      };
    } else {
      const backdrop = document.querySelector(".sidebar-backdrop");
      if (backdrop) document.body.removeChild(backdrop);
    }
  });
  
  // M. 視圖分頁切換
  document.querySelectorAll(".view-tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      switchView(btn.getAttribute("data-view"));
    });
  });

  // 監聽鍵盤 ESC 關閉 Modal
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeDetailModal();
      closeAddModal();
    }
  });
}

function switchView(viewName) {
  state.currentView = viewName;
  
  document.querySelectorAll(".view-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.getAttribute("data-view") === viewName);
  });
  
  const isLocal = viewName === "local-library";
  const isPinterest = viewName === "pinterest-boards";
  const isGlobal = viewName === "global-search";
  
  // 控制本機素材相關元素的顯示
  DOM.galleryGrid.style.display = isLocal && facades.length > 0 ? "grid" : "none";
  DOM.emptyState.style.display = isLocal && facades.length === 0 ? "flex" : "none";
  DOM.activeFiltersBar.style.display = isLocal && DOM.activeTagsList.children.length > 0 ? "flex" : "none";
  DOM.addMaterialBtn.style.display = isLocal ? "flex" : "none";
  DOM.sortSelect.closest(".sort-container").style.display = isLocal ? "flex" : "none";
  
  // 控制 Pinterest 與全球搜尋的顯示
  DOM.pinterestContainer.style.display = isPinterest ? "flex" : "none";
  DOM.globalSearchContainer.style.display = isGlobal ? "flex" : "none";
  
  // 切換搜尋欄 placeholder 提示與啟用狀態
  if (isLocal) {
    DOM.searchInput.placeholder = "搜尋建材、風格、關鍵字或標籤...";
  } else if (isPinterest) {
    DOM.searchInput.placeholder = "輸入關鍵字直接搜尋 Pinterest 全網...";
  } else if (isGlobal) {
    DOM.searchInput.placeholder = "輸入關鍵字直接搜尋全球大師案例...";
  }
  
  // 當切換分頁時，如果上方搜尋欄有文字，同步顯示
  if (state.filters.search) {
    DOM.searchInput.value = state.filters.search;
    DOM.clearSearchBtn.style.display = "flex";
  } else {
    DOM.searchInput.value = "";
    DOM.clearSearchBtn.style.display = "none";
  }
  
  // 觸發對應分頁的篩選/搜尋
  syncFiltersAndTriggerSearch(true);
}

// 載入 Google CSE 腳本的輔助函數
let cseScriptLoading = false;
let cseScriptBlocked = false;

function loadGoogleCSE(onSuccess, onError) {
  if (window.google && window.google.search && window.google.search.cse && window.google.search.cse.element) {
    if (onSuccess) onSuccess();
    return;
  }
  if (document.getElementById("google-cse-script")) {
    if (cseScriptBlocked && onError) onError();
    return;
  }
  cseScriptLoading = true;
  const script = document.createElement("script");
  script.id = "google-cse-script";
  script.type = "text/javascript";
  script.async = true;
  script.src = "https://cse.google.com/cse.js?cx=83dd022b7c6c44933";
  document.body.appendChild(script);
  
  script.onload = () => {
    cseScriptLoading = false;
    if (onSuccess) onSuccess();
  };
  script.onerror = () => {
    cseScriptLoading = false;
    cseScriptBlocked = true;
    if (onError) onError();
  };
}

// 觸發程式化外部搜尋（雙引擎驅動：優先 Google CSE，被 Adblock 阻擋時提供一鍵切換本機備用搜尋）
function triggerSearchInCSE() {
  const isPinterest = state.currentView === "pinterest-boards";
  const isGlobal = state.currentView === "global-search";
  
  if (!isPinterest && !isGlobal) return;
  
  const gname = isPinterest ? "pinterest-search" : "global-search";
  const loadingEl = isPinterest ? DOM.pinterestSearchLoading : DOM.globalSearchLoading;
  const gridEl = isPinterest ? document.getElementById("pinterest-search-grid") : document.getElementById("global-search-grid");
  const cseEl = document.querySelector(`.gcse-searchresults-only[gname="${gname}"]`);
  
  // 1. 如果設定使用本機備用搜尋，直接走後台 API
  if (state.useFallbackSearch) {
    if (cseEl) cseEl.style.display = "none";
    if (gridEl) gridEl.style.display = "grid";
    triggerBackendSearch(gname, gridEl, loadingEl);
    return;
  }
  
  // 2. 否則，正常使用 Google CSE 引擎（在試算軟體 Webview 中無阻擋，直接執行）
  if (gridEl) gridEl.style.display = "none";
  if (cseEl) cseEl.style.display = "block";
  
  if (loadingEl) {
    loadingEl.style.display = "block";
    loadingEl.innerHTML = `
      <span class="material-symbols-outlined animated-spin" style="font-size: 2rem; margin-bottom: 0.5rem; display: inline-block; animation: spin 1.5s linear infinite;">sync</span>
      <p>正在連接 ${isPinterest ? "Pinterest 全網" : "全球大師案例"} 搜尋插頭...</p>
    `;
  }
  
  let cseLoaded = false;
  loadGoogleCSE(
    // 腳本加載成功
    () => {
      let isExecuted = false;
      const checkInterval = setInterval(() => {
        if (window.google && window.google.search && window.google.search.cse && window.google.search.cse.element) {
          const element = google.search.cse.element.getElement(gname);
          if (element) {
            clearInterval(checkInterval);
            isExecuted = true;
            cseLoaded = true;
            if (loadingEl) loadingEl.style.display = "none";
            const q = getCombinedQuery(isGlobal ? "en" : "zh");
            element.execute(q);
          }
        }
      }, 200);
      
      // 8秒防元素初始化超時
      setTimeout(() => {
        if (!isExecuted) {
          clearInterval(checkInterval);
          if (loadingEl) loadingEl.style.display = "none";
        }
      }, 8000);
    },
    // 腳本加載失敗 (被阻擋)
    () => {
      showCseBlockWarning(loadingEl);
    }
  );
  
  // 3.5秒超時監控，如果尚未加載成功，顯示阻擋降級警告
  setTimeout(() => {
    if (!cseLoaded && !state.useFallbackSearch) {
      showCseBlockWarning(loadingEl);
    }
  }, 3500);
}

// 顯示 Google CSE 被阻擋時的降級啟用警告
function showCseBlockWarning(loadingEl) {
  if (!loadingEl) return;
  loadingEl.style.display = "block";
  loadingEl.innerHTML = `
    <div class="external-search-tip" style="max-width: 650px; margin: 0 auto; text-align: left; display: flex; flex-direction: column; align-items: flex-start; background: rgba(197, 168, 128, 0.05); border: 1px dashed var(--accent-gold-glow); border-radius: var(--radius-md); padding: 1.5rem; gap: 0.75rem; box-sizing: border-box; width: 100%;">
      <div style="display: flex; align-items: center; gap: 0.5rem; color: var(--accent-gold); font-weight: 700; font-size: 1rem;">
        <span class="material-symbols-outlined" style="font-size: 1.5rem; color: #f59e0b; vertical-align: middle;">warning</span>
        <span style="vertical-align: middle;">搜尋插頭已受限 (Brave Shields 攔截了 Google CSE 服務)</span>
      </div>
      
      <p style="font-size: 0.85rem; line-height: 1.6; margin: 0; color: var(--text-secondary);">
        因為您正在使用 <strong>Brave 瀏覽器</strong>，其內建的護盾封鎖了 Google 搜尋服務。日後部署在您的土地開發軟體內建視窗（Webview2）時<strong>完全不會受限，請放心使用！</strong>
      </p>

      <div style="width: 100%; border-top: 1px solid rgba(255,255,255,0.08); margin: 0.5rem 0; padding-top: 0.75rem; display: flex; flex-direction: column; gap: 0.75rem;">
        <!-- 解決方案 1 -->
        <div style="display: flex; align-items: flex-start; gap: 0.5rem;">
          <div style="background: rgba(197, 168, 128, 0.15); color: var(--accent-gold); border-radius: 50%; width: 22px; height: 22px; display: flex; align-items: center; justify-content: center; font-size: 0.75rem; font-weight: bold; flex-shrink: 0; margin-top: 2px;">1</div>
          <p style="font-size: 0.8rem; margin: 0; line-height: 1.5; color: var(--text-primary);">
            <strong>【推薦：免設定】用 Google Chrome 或 MS Edge 瀏覽器開啟：</strong><br>
            直接複製網址 <code style="background: rgba(255,255,255,0.06); padding: 0.1rem 0.3rem; border-radius: 3px; font-family: monospace;">http://localhost:8000</code> 在 Chrome 或 Edge 中貼上開啟，無任何阻擋，搜尋完美運作！
          </p>
        </div>

        <!-- 解決方案 2 -->
        <div style="display: flex; align-items: flex-start; gap: 0.5rem;">
          <div style="background: rgba(197, 168, 128, 0.15); color: var(--accent-gold); border-radius: 50%; width: 22px; height: 22px; display: flex; align-items: center; justify-content: center; font-size: 0.75rem; font-weight: bold; flex-shrink: 0; margin-top: 2px;">2</div>
          <p style="font-size: 0.8rem; margin: 0; line-height: 1.5; color: var(--text-primary);">
            <strong>在 Brave 中關閉護盾（一秒解鎖）：</strong><br>
            點擊網址列右側的 🦁 <strong>橘色獅子頭圖示</strong>，並點選關閉 **「防護（Shields are UP）」**。網頁會自動重新整理，搜尋插頭立即正常啟用。
          </p>
        </div>
      </div>

      <div style="width: 100%; border-top: 1px solid rgba(255,255,255,0.08); padding-top: 0.75rem;">
        <p style="font-size: 0.75rem; line-height: 1.5; margin: 0 0 0.5rem 0; color: var(--text-muted);">
          ⚠️ <em>注意：若使用下方的本機備用代理搜尋，頻繁存取極易被 Bing 判定為爬蟲封鎖，進而導致卡片回傳無關的貓咪熱門圖片。</em>
        </p>
        <button type="button" class="btn-switch-fallback" id="btn-switch-fallback" style="background: rgba(255,255,255,0.08); color: var(--text-primary); border: 1px solid rgba(255,255,255,0.15); padding: 0.5rem 1rem; border-radius: var(--radius-sm); font-size: 0.75rem; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 0.3rem; transition: all 0.2s;">
          <span class="material-symbols-outlined" style="font-size: 1rem !important; color: inherit; vertical-align: middle;">cloud_sync</span>
          <span style="vertical-align: middle;">點此嘗試啟用本機備用搜尋</span>
        </button>
      </div>
    </div>
  `;
  
  // 綁定一鍵啟用備用搜尋按鈕點擊事件
  const btn = document.getElementById("btn-switch-fallback");
  if (btn) {
    btn.addEventListener("click", () => {
      state.useFallbackSearch = true;
      triggerSearchInCSE();
    });
  }
}

// 執行本機備用 API 搜尋 (使用 Bing 圖片為後台，自動優化字詞以確保相關度)
function triggerBackendSearch(gname, gridEl, loadingEl) {
  if (loadingEl) {
    loadingEl.style.display = "block";
    loadingEl.innerHTML = `
      <span class="material-symbols-outlined animated-spin" style="font-size: 2rem; margin-bottom: 0.5rem; display: inline-block; animation: spin 1.5s linear infinite;">sync</span>
      <p>正在透過本機備用代理搜尋立面圖片...</p>
    `;
  }
  
  if (gridEl) {
    gridEl.innerHTML = "";
  }
  
  const isGlobal = gname === "global-search";
  
  // 使用高階建築師詞彙映射，獲取最直觀、最具美感的大師設計外觀
  const query = getCombinedQuery(isGlobal ? "en" : "zh");
  
  let finalQuery = query;
  if (gname === "pinterest-search") {
    finalQuery = `site:pinterest.com ${query}`;
  } else {
    finalQuery = `site:archdaily.com OR site:dezeen.com ${query}`;
  }
  
  fetch(`http://127.0.0.1:8989/api/search?q=${encodeURIComponent(finalQuery)}`)
    .then(res => res.json())
    .then(data => {
      if (loadingEl) {
        loadingEl.style.display = "none";
      }
      
      if (!data || data.length === 0) {
        if (gridEl) {
          gridEl.innerHTML = `
            <div style="grid-column: 1/-1; text-align: center; padding: 4rem 2rem; color: var(--text-secondary);">
              <span class="material-symbols-outlined" style="font-size: 3rem; color: var(--text-muted); margin-bottom: 1rem;">sentiment_dissatisfied</span>
              <h3 style="color: var(--text-primary); margin-bottom: 0.5rem; font-size: 1.1rem; font-weight: 600;">未找到相關的建築外觀靈感</h3>
              <p style="font-size: 0.85rem;">請嘗試調整側邊欄的篩選條件，或重新輸入關鍵字。</p>
            </div>
          `;
        }
        return;
      }
      
      if (gridEl) {
        gridEl.innerHTML = data.map(item => {
          const cleanTitle = item.title.replace(/'/g, "\\'").replace(/"/g, '\\"');
          const cleanUrl = item.url;
          
          let sourceLabel = "外部資源";
          let sourceClass = "brand-other";
          if (item.source.includes("pinterest.com")) {
            sourceLabel = "Pinterest";
            sourceClass = "brand-pinterest";
          } else if (item.source.includes("archdaily.com")) {
            sourceLabel = "ArchDaily";
            sourceClass = "brand-archdaily";
          } else if (item.source.includes("dezeen.com")) {
            sourceLabel = "Dezeen";
            sourceClass = "brand-dezeen";
          }
          
          return `
            <div class="facade-card">
              <div class="card-image-wrapper">
                <img src="${item.thumb}" alt="${cleanTitle}" class="card-image" onerror="this.onerror=null; this.src='${cleanUrl}';">
                <span class="external-brand-badge ${sourceClass}">${sourceLabel}</span>
                <div class="card-overlay">
                  <button class="overlay-action-btn import-btn" onclick="window.importExternalImage('${cleanUrl}', '${cleanTitle}')" title="收藏至本機庫">
                    <span class="material-symbols-outlined">download</span>
                    <span>收藏</span>
                  </button>
                  <a href="${item.source}" target="_blank" class="overlay-action-btn view-source-btn" title="查看原始網站">
                    <span class="material-symbols-outlined">open_in_new</span>
                    <span>來源</span>
                  </a>
                </div>
              </div>
              <div class="card-info" style="padding: 1rem; border-top: 1px solid var(--border-color); display: flex; flex-direction: column; gap: 0.25rem;">
                <h4 class="card-title" style="font-size: 0.9rem; font-weight: 600; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; height: 2.8em; margin: 0; color: var(--text-primary);" title="${cleanTitle}">${item.title}</h4>
              </div>
            </div>
          `;
        }).join("");
      }
    })
    .catch(err => {
      console.error(err);
      if (loadingEl) {
        loadingEl.innerHTML = `
          <div class="external-search-tip" style="max-width: 600px; margin: 0 auto; text-align: left; display: flex; flex-direction: column; align-items: flex-start; background: rgba(220, 38, 38, 0.05); border: 1px dashed rgba(220, 38, 38, 0.3); border-radius: var(--radius-md); padding: 1.25rem 1.5rem; gap: 0.5rem;">
            <div style="display: flex; align-items: center; gap: 0.5rem; color: #ef4444; font-weight: 700; font-size: 0.95rem;">
              <span class="material-symbols-outlined" style="font-size: 1.5rem;">error</span>
              <span>後端搜尋代理異常 (錯誤: ${err.message})</span>
            </div>
            <p style="font-size: 0.8rem; line-height: 1.6; margin: 0; color: var(--text-secondary);">
              請確認後台的 <strong>測試伺服器.py</strong> 正常運作中，或重新整頁面。
            </p>
          </div>
        `;
      }
    });
}

// 將外部圖片一鍵導入本機收藏
function importExternalImage(url, title) {
  // 1. 重設表單
  DOM.materialForm.reset();
  currentUploadImage = null;
  
  // 2. 切換為外部圖片網址分頁
  switchUploadTab("upload-url");
  
  // 3. 填入網址與預設案名
  DOM.urlInput.value = url;
  document.getElementById("form-title").value = title || "外部導入素材";
  
  // 4. 顯示圖片預覽
  DOM.imagePreview.src = url;
  DOM.imagePreviewContainer.style.display = "block";
  DOM.dragDropZone.style.display = "none";
  
  // 5. 開啟新增素材視窗
  DOM.addModal.classList.add("active");
  DOM.addModal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
  
  showToast("已自動載入外部圖片，請選取『使用建材』後點擊儲存！");
}

// 註冊為全域 window 函數以便 HTML inline onclick 呼叫
window.importExternalImage = importExternalImage;

let searchDebounceTimeout = null;
function syncFiltersAndTriggerSearch(immediate = false) {
  // 1. 本地過濾永遠即時執行
  renderGallery();
  
  // 2. 外部插頭搜尋執行
  if (state.currentView === "pinterest-boards" || state.currentView === "global-search") {
    clearTimeout(searchDebounceTimeout);
    
    const delay = immediate ? 0 : 450; // 輸入框輸入時防抖動延遲 450ms
    searchDebounceTimeout = setTimeout(() => {
      triggerSearchInCSE();
    }, delay);
  }
}

function getCombinedQuery(lang = "zh") {
  let parts = [];
  let negativeParts = [];
  
  // A. 搜尋字詞 (使用者手動輸入)
  if (state.filters.search) {
    parts.push(state.filters.search);
  }
  
  // B. 建材分類對應到極簡核心英文單字，防止稀釋
  if (state.filters.materials.length > 0) {
    if (lang === "en") {
      const map = {
        "帷幕": "curtain",
        "石材": "stone",
        "鐵件": "metal",
        "磁磚": "terracotta",
        "清水模": "concrete",
        "木質": "timber"
      };
      state.filters.materials.forEach(m => {
        if (map[m]) parts.push(map[m]);
      });
    } else {
      const map = {
        "帷幕": "玻璃帷幕",
        "石材": "石材外牆",
        "鐵件": "金屬格柵",
        "磁磚": "陶磚外牆",
        "清水模": "清水模",
        "木質": "木紋格柵"
      };
      state.filters.materials.forEach(m => {
        if (map[m]) parts.push(map[m]);
      });
    }
  }
  
  // C. 風格標籤對應到極簡核心詞彙
  if (state.filters.styles.length > 0) {
    if (lang === "en") {
      const map = {
        "現代": "modern",
        "工業": "industrial",
        "極簡": "minimalist",
        "古典": "classical"
      };
      state.filters.styles.forEach(s => {
        if (map[s]) parts.push(map[s]);
      });
    } else {
      const map = {
        "現代": "現代風",
        "工業": "工業風",
        "極簡": "極簡風",
        "古典": "古典風"
      };
      state.filters.styles.forEach(s => {
        if (map[s]) parts.push(map[s]);
      });
    }
  }
  
  // D. 樓層標籤與滑桿範圍對應到極簡體量與互斥限制
  let detectedFloor = "all";
  if (state.filters.floorPreset !== "all") {
    detectedFloor = state.filters.floorPreset;
  } else {
    const min = state.filters.floorRange.min;
    const max = state.filters.floorRange.max;
    if (min > 1 || max < 100) {
      if (min >= 15) detectedFloor = "13-999";
      else if (max <= 5) detectedFloor = "1-5";
      else if (min >= 6 && max <= 14) detectedFloor = "6-12";
    }
  }

  if (detectedFloor === "13-999") {
    if (lang === "en") {
      parts.push("skyscraper");
      negativeParts.push("-villa", "-house");
    } else {
      parts.push("摩天大樓");
      negativeParts.push("-別墅", "-低層");
    }
  } else if (detectedFloor === "1-5") {
    if (lang === "en") {
      parts.push("villa");
      negativeParts.push("-skyscraper", "-tower");
    } else {
      parts.push("別墅");
      negativeParts.push("-摩天大樓", "-高層");
    }
  } else if (detectedFloor === "6-12") {
    if (lang === "en") {
      parts.push("mid-rise");
    } else {
      parts.push("中層大樓");
    }
  }
  
  // 整合基本詞彙
  let query = parts.join(" ").trim();
  if (!query) {
    query = lang === "en" ? "building design" : "建築外觀";
  }
  
  // E. 加上極簡且致命的排除詞（控制在 3 個以內，確保搜尋引擎強制遵守）
  if (lang === "en") {
    query += " -detail -interior -drawing";
    if (negativeParts.length > 0) {
      query += " " + negativeParts.join(" ");
    }
  } else {
    query += " -細部 -室內 -圖紙";
    if (negativeParts.length > 0) {
      query += " " + negativeParts.join(" ");
    }
  }
  
  return query;
}

// 啟動應用程式
document.addEventListener("DOMContentLoaded", init);


// ==========================================================================
// 12. 手機版 UI 初始化與互動 (Mobile UI)
// ==========================================================================

function initMobileUI() {
  // 僅在手機寮度內操作，或絕對初始化（如大喢則 CSS 已處理顯示/隱藏）
  const mobileFilterToggle = document.getElementById('mobile-filter-toggle');
  const filterSheet = document.getElementById('filter-sheet');
  const filterSheetOverlay = document.getElementById('filter-sheet-overlay');
  const filterSheetClose = document.getElementById('filter-sheet-close');
  const sheetApplyBtn = document.getElementById('sheet-apply-btn');
  const sheetResetBtn = document.getElementById('sheet-reset-btn');
  const sheetFavBtn = document.getElementById('sheet-fav-btn');
  const mobileFab = document.getElementById('mobile-fab');
  const mobileBottomNav = document.getElementById('mobile-bottom-nav');

  if (!mobileFilterToggle || !filterSheet) return; // 防御

  // ----
  // A. 底部導覽列切換
  // ----
  if (mobileBottomNav) {
    mobileBottomNav.querySelectorAll('.mobile-nav-item').forEach(btn => {
      btn.addEventListener('click', () => {
        const view = btn.getAttribute('data-view');
        // 更新底部 Nav 激活狀態
        mobileBottomNav.querySelectorAll('.mobile-nav-item').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        // 同步切換分頁（共用現有的 switchView 函式）
        switchView(view);
        // FAB 僅在本機素材庫頁顯示
        if (mobileFab) {
          mobileFab.style.display = (view === 'local-library') ? 'flex' : 'none';
        }
      });
    });
  }

  // 同步桌面版 view-tab-btn 的切換動作至底部 Nav
  const origSwitchView = switchView;
  // 不需要覆寫，分頁已共用

  // ----
  // B. 篩選快捷按鈕 → 開啟抽屜
  // ----
  mobileFilterToggle.addEventListener('click', () => openFilterSheet());

  // ----
  // C. 關閉抽屜
  // ----
  if (filterSheetClose) filterSheetClose.addEventListener('click', () => closeFilterSheet());
  if (filterSheetOverlay) filterSheetOverlay.addEventListener('click', () => closeFilterSheet());

  // ----
  // D. 抽屜內建材築選 chip 變更事件（即時同步至主篩選狀態）
  // ----
  document.querySelectorAll('.sheet-filter-cb').forEach(cb => {
    cb.addEventListener('change', () => {
      const type = cb.getAttribute('data-type');
      const val = cb.value;
      if (type === 'material') {
        if (cb.checked) {
          if (!state.filters.materials.includes(val)) state.filters.materials.push(val);
          // 同步 sidebar checkbox
          const sidebarCb = document.querySelector(`#material-filters input[value="${val}"]`);
          if (sidebarCb) sidebarCb.checked = true;
        } else {
          state.filters.materials = state.filters.materials.filter(m => m !== val);
          const sidebarCb = document.querySelector(`#material-filters input[value="${val}"]`);
          if (sidebarCb) sidebarCb.checked = false;
        }
      } else if (type === 'style') {
        if (cb.checked) {
          if (!state.filters.styles.includes(val)) state.filters.styles.push(val);
          const sidebarCb = document.querySelector(`#style-filters input[value="${val}"]`);
          if (sidebarCb) sidebarCb.checked = true;
        } else {
          state.filters.styles = state.filters.styles.filter(s => s !== val);
          const sidebarCb = document.querySelector(`#style-filters input[value="${val}"]`);
          if (sidebarCb) sidebarCb.checked = false;
        }
      }
      updateMobileFilterBadge();
    });
  });

  // ----
  // E. 抽屜內樓層預設按鈕
  // ----
  document.querySelectorAll('.sheet-floor-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.sheet-floor-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const range = btn.getAttribute('data-range');
      state.filters.floorPreset = range;
      // 同步 sidebar 的樓層按鈕
      document.querySelectorAll('#floor-range-presets button').forEach(sb => {
        sb.classList.toggle('active', sb.getAttribute('data-range') === range);
      });
      updateMobileFilterBadge();
    });
  });

  // ----
  // F. 抽屜內收藏按鈕
  // ----
  if (sheetFavBtn) {
    sheetFavBtn.addEventListener('click', () => {
      state.filters.favoritesOnly = !state.filters.favoritesOnly;
      sheetFavBtn.classList.toggle('active', state.filters.favoritesOnly);
      // 同步 sidebar 收藏按鈕
      DOM.favOnlyBtn.classList.toggle('active', state.filters.favoritesOnly);
      updateMobileFilterBadge();
    });
  }

  // ----
  // G. 抽屜 「重置」按鈕
  // ----
  if (sheetResetBtn) {
    sheetResetBtn.addEventListener('click', () => {
      clearAllFilters();
      syncSheetWithState();
      updateMobileFilterBadge();
    });
  }

  // ----
  // H. 抽屜 「套用篩選」按鈕
  // ----
  if (sheetApplyBtn) {
    sheetApplyBtn.addEventListener('click', () => {
      syncFiltersAndTriggerSearch(true);
      closeFilterSheet();
      updateMobileFilterBadge();
    });
  }

  // ----
  // I. FAB 按鈕→開啟新增素材 Modal
  // ----
  if (mobileFab) {
    mobileFab.addEventListener('click', () => openAddModal());
    // FAB 預設動画（待模拟載入完成後輕微延遲）
    setTimeout(() => {
      if (mobileFab.style.display !== 'none') {
        mobileFab.style.animation = 'fab-pulse 2.5s ease-in-out infinite';
      }
    }, 1500);
  }

  // ----
  // J. 手勢支援：向下滑動關閉抽屜
  // ----
  let sheetTouchStartY = 0;
  let sheetTouchCurrentY = 0;

  filterSheet.addEventListener('touchstart', e => {
    sheetTouchStartY = e.touches[0].clientY;
  }, { passive: true });

  filterSheet.addEventListener('touchmove', e => {
    sheetTouchCurrentY = e.touches[0].clientY;
    const delta = sheetTouchCurrentY - sheetTouchStartY;
    if (delta > 0) {
      filterSheet.style.transform = `translateY(${delta}px)`;
    }
  }, { passive: true });

  filterSheet.addEventListener('touchend', () => {
    const delta = sheetTouchCurrentY - sheetTouchStartY;
    filterSheet.style.transform = '';
    if (delta > 80) {
      // 向下滑超過 80px 則關閉
      closeFilterSheet();
    }
    sheetTouchStartY = 0;
    sheetTouchCurrentY = 0;
  }, { passive: true });

  // ----
  // K. 首次載入後同步 sidebar 的篩選狀態至抽屜
  // ----
  syncSheetWithState();
  updateMobileFilterBadge();
  updateSheetFavBadge();
}

// 開啟篩選抽屜
function openFilterSheet() {
  const filterSheet = document.getElementById('filter-sheet');
  const filterSheetOverlay = document.getElementById('filter-sheet-overlay');
  if (!filterSheet) return;

  // 開啟前同步現有篩選狀態至抽屜
  syncSheetWithState();
  updateSheetFavBadge();

  if (filterSheetOverlay) {
    filterSheetOverlay.style.display = 'block';
    requestAnimationFrame(() => filterSheetOverlay.classList.add('active'));
  }
  filterSheet.classList.add('active');
  filterSheet.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
}

// 關閉篩選抽屜
function closeFilterSheet() {
  const filterSheet = document.getElementById('filter-sheet');
  const filterSheetOverlay = document.getElementById('filter-sheet-overlay');
  if (!filterSheet) return;

  filterSheet.classList.remove('active');
  filterSheet.setAttribute('aria-hidden', 'true');
  filterSheet.style.transform = '';

  if (filterSheetOverlay) {
    filterSheetOverlay.classList.remove('active');
    setTimeout(() => {
      filterSheetOverlay.style.display = 'none';
    }, 300);
  }
  document.body.style.overflow = '';
}

// 將 sidebar 篩選狀態同步至 Filter Sheet
function syncSheetWithState() {
  // 建材 chip
  document.querySelectorAll('#sheet-material-filters .sheet-filter-cb').forEach(cb => {
    cb.checked = state.filters.materials.includes(cb.value);
  });

  // 風格 chip
  document.querySelectorAll('#sheet-style-filters .sheet-filter-cb').forEach(cb => {
    cb.checked = state.filters.styles.includes(cb.value);
  });

  // 樓層預設
  const currentPreset = state.filters.floorPreset || 'all';
  document.querySelectorAll('.sheet-floor-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-range') === currentPreset);
  });

  // 收藏按鈕
  const sheetFavBtn = document.getElementById('sheet-fav-btn');
  if (sheetFavBtn) {
    sheetFavBtn.classList.toggle('active', state.filters.favoritesOnly);
  }
}

// 更新手機版篩選數量徽章
function updateMobileFilterBadge() {
  const badge = document.getElementById('mobile-filter-badge');
  if (!badge) return;

  let count = 0;
  count += state.filters.materials.length;
  count += state.filters.styles.length;
  if (state.filters.floorPreset && state.filters.floorPreset !== 'all') count++;
  if (state.filters.favoritesOnly) count++;
  if (state.filters.search) count++;

  badge.textContent = count;
  badge.style.display = count > 0 ? 'flex' : 'none';
}

// 更新抽屜內收藏數量徽章
function updateSheetFavBadge() {
  const badge = document.getElementById('sheet-fav-badge');
  if (!badge) return;
  const favCount = facades.filter(f => f.isFavorite).length;
  badge.textContent = favCount;
}
